types.FatmsHeapEnt:
/* prfile_mod.c heap bookkeeping (g_heapTbl, 128 entries). mem = -1 while being created. */
typedef struct {
    SceUID heap; /* 0x0 */
    void *mem; /* 0x4 */
} FatmsHeapEnt;

types.FatmsMountInfo:
/* prfile_mod.c mount state (0x4C bytes, cleared on the last umount). */
typedef struct {
    s32 unit; /* 0x0, -1 = none */
    u8 pad4[0x48];
} FatmsMountInfo;

types.FatmsPrivate:
/* Per-iob private block checked by check_heap_alive: mode 0x10 = file, 2 = directory.
   2.60+ moved the file's heap/pool id to 0xC. */
typedef struct {
    s32 mode; /* 0x0 */
    s32 unk4; /* 0x4, PrFILE file/dir handle */
    SceUID dirHeap; /* 0x8 */
#if FW_VERSION >= 260
    SceUID fileHeap; /* 0xC */
#else
    u8 padC[0x60];
    SceUID fileHeap; /* 0x6C */
#endif
} FatmsPrivate;

types.PfCwd:
typedef struct {
    s32 unk0;
    s32 unk4;
    s32 unk8;
    char path[0x104]; /* 0xC */
} PfCwd;

types.PfDateTime:
/* PrFILE set-time arguments (stub cmd 0x22). */
typedef struct {
    s32 year;
    s32 month;
    s32 day;
} PfDate;

typedef struct {
    s32 hour;
    s32 minute;
    s32 second;
} PfTime;

types.PfDirCursor:
/* PrFILE directory cursor: the current directory entry and its position (D_00027934; D_00027800 points at one).
   Fields past 0x30 are only known for 1.x (2.01+ grew the record). */
typedef struct {
    FatDirEnt de; /* 0x0 */
#if FW_VERSION >= 201
    u8 pad20[0x20];
#else
    u8 pad20[0x10];
#endif
    u32 sector; /* 0x30 (2.01+: 0x40), sector holding the entry */
    u8 pad34[4];
    s32 unk38; /* 0x38 */
    u32 dirtyMask; /* 0x3C, dirty sectors of the directory buffer */
    u8 pad40[4];
    s32 unk44; /* 0x44 */
    u8 pad48[4];
    u32 unk4C; /* 0x4C (2.01+: 0x5C), flags: 2 = buffer dirty, 0x10 */
    u8 pad50[8];
    s32 unk58; /* 0x58 */
#if FW_VERSION < 201
    u8 pad5C[0x100];
    char path[0x104]; /* 0x15C */
    s8 drive; /* 0x260 */
    u8 pad261[3];
#endif
} PfDirCursor;

types.PfDirInfo:
/* PrFILE directory search record (stub cmd 6), kept at FatmsPrivate + 0x568. */
typedef struct {
    u8 pad0[0x118];
    u16 mtime; /* 0x118 */
    u16 mdate; /* 0x11A */
    u32 size; /* 0x11C */
    s8 attr; /* 0x120 */
    char shortName[13]; /* 0x121 */
    char longName[0x20E]; /* 0x12E */
    u16 ctime; /* 0x33C */
    u16 cdate; /* 0x33E */
    u16 adate; /* 0x340 */
} PfDirInfo;

types.PfDrives:
/* Drive count word: cleared as a word, read as its low byte. */
typedef union {
    s32 word;
    u8 count;
} PfDrives;

types.PfFatInfo:
/* Mounted FAT volume geometry (D_0001BCC4). */
typedef struct {
    u32 rootStart; /* 0x0, first root-directory sector */
    u32 dataStart; /* 0x4, first sector of cluster 2 */
    u32 unk8;
    u32 clusterCount; /* 0xC, first invalid cluster number */
    u32 cacheSectors; /* 0x10, FAT sectors held in the FAT buffer */
    u32 unk14;
    u32 clusterShift; /* 0x18, log2(sectors per cluster) */
    u32 unk1C;
    u32 rootSectors; /* 0x20 */
} PfFatInfo;

types.PfFile:
/* PrFILE open-file record (table D_0001BEFC[10]; 0x264 bytes in 1.x, 0x700 in 2.01+). */
typedef struct {
    u8 pad0[0xD];
    s8 flags; /* 0xD, bit 7 = in use */
    u8 padE[0xE];
    u32 size; /* 0x1C */
    u32 pos; /* 0x20, current file position */
#if FW_VERSION >= 201
    u8 pad24_201[0x10]; /* placement of the 2.01 insertion within 0x24..0x60 is a guess */
#endif
    s32 unk24;
    s32 unk28;
    u8 pad2C[4];
    s32 unk30;
    u8 pad34[8];
    s32 unk3C;
    s32 unk40;
    u8 pad44[8];
    s32 unk4C;
    s32 unk50; /* 0x50 (2.01+: 0x60) */
    u8 unk54;
#if FW_VERSION >= 201
    u8 pad55[0x700 - 0x65];
#else
    u8 pad55[0x264 - 0x55];
#endif
} PfFile;

types.PfGeometry:
/* Current volume geometry (D_0002790C, 0x28 bytes copied from PfDrive.geometry). */
typedef struct {
    u16 bytesPerSector; /* 0x0 */
    u16 sectorsPerCluster; /* 0x2 */
    u16 fatStart; /* 0x4, first FAT sector */
    u8 pad6[0xA];
    u32 fatSectors; /* 0x10, sectors per FAT */
    u8 pad14[4];
    u16 unk18; /* 0x18 */
    u8 pad1A[0xE];
} PfGeometry;
typedef char chk_PfGeometry[(sizeof(PfGeometry) == 0x28) ? 1 : -1];

types.PfSavedEnt:
/* Saved directory-entry position (D_00019E2C), restored by func_00013E3C. */
typedef struct {
    s32 unk0; /* 0x0 */
    s32 unk4; /* 0x4 */
    s32 unk8; /* 0x8 */
    s8 drive; /* 0xC */
    char path[0x104]; /* 0xD */
    s8 pending; /* 0x111 */
} PfSavedEnt;

types.PfStat:
/* PrFILE stat result (stub cmd 0xC), FAT DOS date/time words. */
typedef struct {
    u16 mtime; /* 0x0 */
    u16 pad2;
    u16 mdate; /* 0x4 */
    u16 pad6;
    u32 size; /* 0x8 */
    s8 attr; /* 0xC */
    u8 padD[3];
    u16 ctime; /* 0x10 */
    u16 pad12;
    u16 cdate; /* 0x14 */
    u16 pad16;
    u16 adate; /* 0x18 */
    u16 pad1A;
    u8 pad1C[4];
} PfStat;

types.PfVolume:
/* PrFILE volume / drive record (partial; D_000276E4 points at the current one). */
typedef struct {
    unsigned long flags; /* 0x0, bit 0 = mounted, 0x8000 = FAT16, 0x1000 = FAT32 (neither = FAT12) */
    u32 fatBufSector; /* 0x4, first sector in fatBuf (-1 = invalid) */
    u8 pad8[4];
    u8 *fatBuf; /* 0xC, FAT sector buffer */
    u8 pad10[0xC];
    s32 unk1C; /* 0x1C */
} PfVolume;

types.PfVolumeDrive:
/* PrFILE drive registration (D_00027CC8[drive - A]). */
typedef struct {
    void *ops; /* 0x0, 0x10 bytes of driver functions copied to D_000276E8 */
    void *geometry; /* 0x4, 0x28 bytes copied to D_0002790C */
    PfVolume *vol; /* 0x8 */
} PfDrive;

